brand_css_dark:
:root {
--radius-none: 0;
--radius-sm: 4px;     /* 배지 .prid__nm, 체크박스 */
--radius-md: 8px;     /* 기본 — 입력·버튼·드롭다운(실측 최빈) */
--radius-lg: 12px;    /* 카드·모달 */
--radius-xl: 24px;    /* 큰 알약형 버튼 .error__btn(높이 48px) */
--radius-full: 9999px; /* 녹음 점·아바타·토글 */
--shadow-none: none;                              /* 기본 — 구획은 면 색과 1px 선 */
--shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.06);       /* 입력 포커스 보조 (추정) */
--shadow-md: 0 6px 20px 10px rgba(0, 0, 0, 0.05); /* 드롭다운·말줄임 메뉴 — 실측 #0000000d */
--shadow-lg: 0 12px 32px rgba(0, 0, 0, 0.12);     /* 모달 (추정) */
--shadow-xl: 0 20px 48px rgba(0, 0, 0, 0.18);     /* 전체 화면 시트 (추정) */
--duration-fast: 150ms;   /* (추정) 호버 색 */
--duration-base: 200ms;   /* 실측 — transition:.2s, 패널 translate .2s */
--duration-slow: 400ms;   /* (추정) 시트 등장 */
--ease-out: cubic-bezier(0.25, 0.1, 0.25, 1);    /* 실측 CSS 에 따로 지정 없음 → 브라우저 기본 ease */
--ease-in-out: cubic-bezier(0.42, 0, 0.58, 1);   /* (추정) */
}
:root {
  /* Primary - 인디고 (다크 기본: 한 단계 밝은 #5C7CFA 가 기본 강조) */
  --color-primary-50:  #1B2140;  /* (추정) #5C7CFA 12% 를 #111 에 합성 — 선택 행 면 */
  --color-primary-100: #232C5C;  /* (추정) 합성 */
  --color-primary-200: #2F3C82;  /* (추정) 합성 */
  --color-primary-300: #4263EB;  /* 실측 값 재배치 */
  --color-primary-400: #4C6EF5;  /* 실측 — 라이트 기본값 */
  --color-primary-500: #5C7CFA;  /* 실측 — 다크 기본. BETA 표식·링크·편집 버튼 */
  --color-primary-600: #748FFC;  /* (추정) Open Color indigo 4 — 다크에선 호버가 밝아지는 방향 */
  --color-primary-700: #91A7FF;  /* (추정) indigo 3 */
  --color-primary-800: #BAC8FF;  /* (추정) indigo 2 */
  --color-primary-900: #DBE4FF;  /* (추정) indigo 1 */

  /* Secondary - 로고는 다크에서 공식 흰색 버전 */
  --color-secondary-500: #FFFFFF;  /* 로고 흰색 버전 — 공식 gnb-adotai-dark.svg */
  --color-secondary-300: rgba(255, 255, 255, 0.35); /* 눈 하이라이트 (opacity .35) */
  --color-plan-500:      #598AFB;  /* 실측 — 다크의 요금제 업그레이드 버튼 */

  /* Neutral - 다크 반전 (0 = 가장 어두움) */
  --color-neutral-0:    #111111;  /* 본문 바탕 — 실측 */
  --color-neutral-50:   #1A1A1A;  /* 좌측 레일 .gnb 바탕 — 실측 */
  --color-neutral-100:  #212121;  /* 패널 경계 — 실측 */
  --color-neutral-200:  #292929;  /* 구분선·밝은 버튼 위 글자 */
  --color-neutral-300:  #3C3D41;  /* 비활성 면 — 실측 */
  --color-neutral-500:  #A7A7A7;  /* 보조 글자 — 실측 */
  --color-neutral-600:  #C3C3C3;  /* 2차 글자 */
  --color-neutral-700:  #C2C2C2;  /* 반투명 호버 면의 원색 — 실측 #C2C2C212 */
  --color-neutral-800:  #DADADA;  /* 버튼 호버 */
  --color-neutral-900:  #EBEBEB;  /* 밝은 채움 버튼 — 실측 .error__btn(다크) */
  --color-neutral-1000: #FFFFFF;

  /* Semantic */
  --color-success-bg: rgba(64, 192, 87, 0.14);  /* (추정) */
  --color-success-fg: #51CF66;                  /* (추정) Open Color green 5 */
  --color-warning-bg: rgba(252, 196, 25, 0.14); /* (추정) */
  --color-warning-fg: #FCC419;                  /* (추정) Open Color yellow 5 */
  --color-error-bg:   rgba(250, 82, 82, 0.14);  /* (추정) */
  --color-error-fg:   #FA5252;                  /* 실측 — 다크의 빨강 */
  --color-info-bg:    rgba(28, 126, 214, 0.14); /* (추정) */
  --color-info-fg:    #4DABF7;                  /* (추정) Open Color blue 4 */

  /* Surface (배경 위계) */
  --bg-base:     #111111;  /* 본문·목록 패널 — 실측 */
  --bg-subtle:   #1A1A1A;  /* 좌측 레일, 재생 막대 — 실측 */
  --bg-elevated: #212121;  /* 카드·드롭다운 — 실측 */
  --bg-overlay:  rgba(0, 0, 0, 0.55);  /* (추정) 모달 딤 */
  --bg-hover:    rgba(194, 194, 194, 0.07);  /* 실측 #C2C2C212 — 목록 호버·선택 */

  /* Text 위계 */
  --text-primary:   #E4E4E4;  /* 본문 — 실측(44회) */
  --text-secondary: #C3C3C3;
  --text-tertiary:  #A7A7A7;  /* 캡션 — 실측 */
  --text-on-primary: #FFFFFF;
  --text-inverse:   #292929;  /* 밝은 버튼 위 — 실측 */
  --text-disabled:  #555555;

  /* Border */
  --border-default: #292929;
  --border-subtle:  #212121;
  --border-strong:  #3E3E3E;
  --border-focus:   #5C7CFA;
}

[data-theme="light"] {
  --color-primary-50: #EDF2FF; --color-primary-100: #DBE4FF; --color-primary-200: #BAC8FF; --color-primary-300: #91A7FF;
  --color-primary-400: #5C7CFA; --color-primary-500: #4C6EF5; --color-primary-600: #4263EB; --color-primary-700: #3B5BDB;
  --color-primary-800: #364FC7; --color-primary-900: #333784;
  --color-secondary-500: #333784; --color-secondary-300: #A2A7CF; --color-plan-500: #4778E9;
  --color-neutral-0: #FFFFFF; --color-neutral-50: #F5F5F5; --color-neutral-100: #EBEBEB; --color-neutral-200: #DADADA;
  --color-neutral-300: #C3C3C3; --color-neutral-500: #7F7F7F; --color-neutral-600: #555555; --color-neutral-700: #3E3E3E;
  --color-neutral-800: #292929; --color-neutral-900: #111111; --color-neutral-1000: #000000;
  --color-success-bg: #EBFBEE; --color-success-fg: #2F9E44; --color-warning-bg: #FFF9DB; --color-warning-fg: #F08C00;
  --color-error-bg: #FFF5F5; --color-error-fg: #F03E3E; --color-info-bg: rgba(28, 126, 214, 0.08); --color-info-fg: #1C7ED6;
  --bg-base: #FFFFFF; --bg-subtle: #F5F5F5; --bg-elevated: #FFFFFF; --bg-overlay: rgba(0, 0, 0, 0.30); --bg-hover: rgba(62, 62, 62, 0.07);
  --text-primary: #1A1A1A; --text-secondary: #555555; --text-tertiary: #7F7F7F; --text-on-primary: #FFFFFF;
  --text-inverse: #DADADA; --text-disabled: #C3C3C3;
  --border-default: #EBEBEB; --border-subtle: #F5F5F5; --border-strong: #C3C3C3; --border-focus: #4C6EF5;
}




.btn { height: 44px; padding: 0 20px; border: 0; border-radius: var(--radius-md); font: 600 15px/1 'Pretendard Variable', Pretendard, system-ui, sans-serif; cursor: pointer; transition: background-color var(--duration-base) var(--ease-out); }
/* Primary — 웹 실측: 검정 채움 버튼(.pln__stgo #111 / 글자 #DADADA) */
.btn-primary { background: var(--color-neutral-900); color: var(--text-inverse); }
.btn-primary:hover { background: var(--color-neutral-800); }
.btn-primary:active { background: var(--color-neutral-1000); }
.btn-primary:disabled { background: var(--color-neutral-100); color: var(--text-disabled); cursor: not-allowed; }
.btn-primary.is-loading { color: transparent; position: relative; }
.btn-primary.is-loading::after { content: ""; position: absolute; inset: 0; margin: auto; width: 16px; height: 16px; border: 2px solid var(--text-inverse); border-right-color: transparent; border-radius: 50%; animation: spin 0.8s linear infinite; }
/* Secondary — 인디고 채움(요금제 업그레이드 .pln__upg 계열) */
.btn-secondary { background: var(--color-primary-500); color: var(--text-on-primary); }
.btn-secondary:hover { background: var(--color-primary-600); }
.btn-secondary:active { background: var(--color-primary-700); }
.btn-secondary:disabled { background: var(--color-primary-100); color: var(--text-disabled); }
/* Ghost — 회색 반투명 면(.lnb__lnk:hover #3E3E3E12) */
.btn-ghost { background: transparent; color: var(--text-primary); }
.btn-ghost:hover { background: var(--bg-hover); }
.btn-ghost:active { background: rgba(62, 62, 62, 0.10); }
.btn-ghost:disabled { color: var(--text-disabled); }
/* Danger — 삭제 텍스트 버튼(.hstry__btn--del #F03E3E) */
.btn-danger { background: transparent; color: var(--color-error-fg); }
.btn-danger:hover { background: var(--color-error-bg); }
.btn-danger:active { background: #FFE3E3; }
.btn-danger:disabled { color: var(--text-disabled); }
@keyframes spin { to { transform: rotate(360deg); } }
.input { height: 44px; padding: 0 14px; border: 1px solid var(--border-default); border-radius: var(--radius-md); background: var(--bg-base); color: var(--text-primary); font-size: 15px; }
.input::placeholder { color: var(--text-tertiary); }
.input:focus { outline: 0; border-color: var(--border-focus); }
.input.is-error { border-color: var(--color-error-fg); }           /* 폴더 이름 중복 .lnb__editError--duplicate */
.input-error-text { color: var(--color-error-fg); font-size: 12px; }
.input:disabled { background: var(--bg-subtle); color: var(--text-disabled); }
.card { background: var(--bg-base); border: 1px solid var(--border-default); border-radius: var(--radius-lg); padding: var(--space-md); }
.card--emphasis { background: var(--bg-subtle); border-color: transparent; }   /* 레일과 같은 #F5F5F5 면 */
.card--outlined { background: transparent; border: 1px solid var(--border-strong); }
.card:hover { background: rgba(62, 62, 62, 0.04); }
.badge { display: inline-flex; align-items: center; height: 20px; padding: 0 8px; border-radius: var(--radius-sm); font-size: 10px; font-weight: 700; }
.badge--solid  { background: var(--color-primary-500); color: #fff; }             /* 레일의 BETA 표식 .gnb__beta */
.badge--subtle { background: rgba(76, 110, 245, 0.10); color: var(--color-primary-500); } /* 요금제 이름 .prid__nm */
.badge--outline { background: transparent; border: 1px solid var(--border-strong); color: var(--text-secondary); }
.dot-new { width: 6px; height: 6px; border-radius: 50%; background: var(--color-error-fg); } /* 새 소식 .nt__new */
.gnb { width: 72px; background: var(--bg-subtle); color: var(--text-primary); display: flex; flex-direction: column; align-items: center; justify-content: space-between; padding: 10px 0 24px; }
.gnb__lnk { width: 48px; padding-top: 30px; font-size: 9px; font-weight: 600; line-height: 1.45; text-align: center; position: relative; border-radius: 12px; }
.gnb__lnk[aria-current="page"]::before, .gnb__lnk:active::before { background: rgba(62, 62, 62, 0.10); } /* 실측 #3E3E3E1A */
.gnb__rcd { color: var(--color-error-fg); font-size: 9px; font-weight: 600; }  /* 「녹음 중」 표시 */
.lnb { width: 264px; background: var(--bg-base); border-right: 1px solid var(--border-default); padding: 11px 12px 0; }
.lnb__lnk { height: 48px; padding-left: 38px; border-radius: 13px; font-size: 15px; font-weight: 600; color: var(--text-primary); }
.lnb__lnk:hover { background: var(--bg-hover); }                      /* 실측 #3E3E3E12 */
